	(206, 'EDGE prix_max 09', 'REF-00206', 'Produit de test « prix_max ». Désigner chez longtemps désirer réflexion soi vouloir désespoir ruine coucher présence.', 'Montres', '2025-02-12 01:51:00+01', 3, 12),
